css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
.button-pill{ display: inline-block; padding: 12px 24px; border: 1px solid currentColor; border-radius: 999px; font-family: Switzer, Arial, sans-serif; font-size: 17px; line-height: 1.3; font-weight: 400; color: inherit; text-decoration: none; white-space: nowrap; transition: background-color 0.2s ease, color 0.2s ease; }
.button-pill:hover{ background-color: rgba(128, 128, 128, 0.18); }
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }}
@media screen and (max-width: 479px){.button-pill{ font-size: 16px; padding: 11px 20px; white-space: normal; text-align: center; }}
.cta-section { padding-top: 40px; padding-bottom: 120px; background-color: #13181d; color: #13181d; font-family: Switzer, Arial, sans-serif; }
.cta-panel { display: flex; align-items: stretch; gap: 80px; padding: 20px; border-radius: 4px; background-color: #d1d1d1; }
.cta-text { display: flex; flex: 1 1 0; min-width: 0; flex-direction: column; align-items: flex-start; justify-content: center; gap: 32px; padding: 80px 0 80px 80px; }
.cta-label { margin: 0; font-size: 18px; line-height: 1.25; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; }
.cta-lead { margin: 0; font-size: 36px; line-height: 1.2; font-weight: 400; letter-spacing: -0.02em; }
.cta-photo { flex: 0 0 42%; min-height: 420px; overflow: hidden; border-radius: 2px; }
.cta-photo-img { display: block; width: 100%; height: 100%; object-fit: cover; }

@media screen and (max-width: 991px) {
  .cta-panel { gap: 40px; }
  .cta-text { padding: 48px 0 48px 28px; }
  .cta-lead { font-size: 28px; }
  .cta-photo { min-height: 360px; }
}
@media screen and (max-width: 767px) {
  .cta-section { padding-bottom: 88px; }
  .cta-panel { flex-direction: column; gap: 32px; padding: 16px; }
  .cta-text { padding: 28px 8px 0 8px; gap: 24px; }
  .cta-label { font-size: 15px; }
  .cta-lead { font-size: 25px; }
  .cta-photo { flex: none; min-height: 0; aspect-ratio: 3 / 2; }
}
@media screen and (max-width: 479px) {
  .cta-lead { font-size: 22px; }
}
